INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/uberblick-trassenanmeldung-zum-netzfahrplan-und-im-gelegenheitsverkehr.md','Überblick - Trassenanmeldung zum Netzfahrplan und im Gelegenheitsverkehr','**Trassenanmeldung im Netzfahrplan** Die DB InfraGO AG konstruiert die Trassen des Netzfahrplans auf der Basis von Trassenanmeldungen. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtv','bootstrap:f8dfc1a873a48ca396ea046a5cc9add01212dc42661928708329bb77e6998fff','c4f4a4a33ca9a2585d642a4b62f437dd2420b8651e9e19f75db81168a09c86cb','2026-08-08T12:35:15Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/ueberblick-10907392","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/ueberblick-10907392","source_id":"src_15a62986bf5cb9217f1c","source_version_id":"sv_7b15f5b01728d3b71a6f9897"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
